      return "error";
    case "orphan":
    case "crowded-diagram":
    case "tight-spacing":
      return "warning";
    case "truncated-state":
      return "info";
  }
}

function visualFindingRank(finding: VisualFinding): number {
  switch (visualFindingSeverity(finding)) {
    case "error": return 0;
    case "warning": return 1;
    case "info": return 2;
  }
}

