    const px = -dy / len;
    const py = dx / len;
    const amp = 7; // zigzag amplitude
    let d = `M ${p1.x},${p1.y}`;
    for (let i = 1; i < segments; i++) {
      const t = i / segments;
      const bx = p1.x + dx * t;
      const by = p1.y + dy * t;
      const offset = (i % 2 === 1 ? amp : -amp);
      d += ` L ${bx + px * offset},${by + py * offset}`;
    }
    d += ` L ${p2.x},${p2.y}`;
    linkElement = (
      <path className="link-line" d={d} fill="none" stroke={color} markerEnd={markerEnd} />
