  let linkElement: React.ReactNode;
  if (edgePath && !isLightning) {
    // Use pre-computed edge path (curved or straight)
    linkElement = (
      <path className="link-line" d={edgePath.d} fill="none" stroke={color}
        markerEnd={markerEnd} markerStart={markerStart} />
    );
  } else if (isLightning) {
    // Zigzag path from p1 to p2
    const dx = p2.x - p1.x;
    const dy = p2.y - p1.y;
    const len = Math.sqrt(dx * dx + dy * dy);
    const segments = Math.max(3, Math.round(len / 30));
    // Perpendicular unit vector
    const px = -dy / len;
    const py = dx / len;
    const amp = 7; // zigzag amplitude
    let d = `M ${p1.x},${p1.y}`;
    for (let i = 1; i < segments; i++) {
      const t = i / segments;
      const bx = p1.x + dx * t;
      const by = p1.y + dy * t;
      const offset = (i % 2 === 1 ? amp : -amp);
      d += ` L ${bx + px * offset},${by + py * offset}`;
    }
    d += ` L ${p2.x},${p2.y}`;
    linkElement = (
      <path className="link-line" d={d} fill="none" stroke={color} markerEnd={markerEnd} />
    );
  } else {
    linkElement = (
      <line
        className="link-line"
        x1={p1.x} y1={p1.y} x2={p2.x} y2={p2.y}
        stroke={color}
        markerEnd={markerEnd}
        markerStart={markerStart}
      />
    );
  }

  // Hit area: wider invisible path for easier clicking
  const hitAreaStyle: React.CSSProperties = { cursor: "pointer" };
  let hitArea: React.ReactNode = null;
  if (onClick) {
    if (edgePath && !isLightning) {
      hitArea = <path d={edgePath.d} fill="none" stroke="transparent" strokeWidth={12} style={hitAreaStyle} onClick={onClick} />;
    } else if (!isLightning) {
      hitArea = <line x1={p1.x} y1={p1.y} x2={p2.x} y2={p2.y} stroke="transparent" strokeWidth={12} style={hitAreaStyle} onClick={onClick} />;
    }
  }

  return (
