688	  const instruments = objects.filter((a) => links.some((l) => l.type === "instrument" && l.source === a.thing) && !agents.some((ag) => ag.thing === a.thing));
689	  const consumed = objects.filter((a) => links.some((l) => l.type === "consumption" && l.source === a.thing));
690	  const results = objects.filter((a) => links.some((l) => l.type === "result" && l.target === a.thing));
691	  const exhibited = objects.filter((a) => links.some((l) => l.type === "exhibition" && (l.source === a.thing || l.target === a.thing)));
692	  const remaining = objects.filter((a) =>
693	    !agents.some((x) => x.thing === a.thing) &&
694	    !instruments.some((x) => x.thing === a.thing) &&
695	    !consumed.some((x) => x.thing === a.thing) &&
696	    !results.some((x) => x.thing === a.thing) &&
