729	  }
730	
731	  // Top band: exhibited attributes + beneficiary
732	  let topX = 50;
733	  for (const app of exhibited) {
734	    const size = autoSizeAppearance(model, app);
735	    if (!isPinned(app)) patches.push({ thingId: app.thing, opdId, patch: { x: topX, y: 40, ...size } });
736	    topX += size.w + VISUAL_RULES.spacing.nodeGap;
