593	function layoutStructuralCluster(
594	  model: Model, opdId: string, apps: Appearance[], links: Link[],
595	): LayoutSuggestion {
596	  const visibleThings = new Set(apps.map((a) => a.thing));
597	  const clusters = findStructuralClusters(links, visibleThings);
598	  if (clusters.length === 0) return { strategy: "none", patches: [], findings: [] };
599	
600	  const patches: AppearancePatch[] = [];
601	  const placed = new Set<string>();
602	  let nextClusterY = 40;
603	  const clusterBaseX = 120;
604	  const clusterMaxWidth = 760;
605	
606	  for (const cluster of clusters) {
607	    const parentApp = apps.find((a) => a.thing === cluster.parentId);
608	    if (!parentApp) continue;
609	    const childApps = cluster.childIds.map((id) => apps.find((a) => a.thing === id)).filter(Boolean) as Appearance[];
610	    if (childApps.length === 0) continue;
611	
612	    const parentSize = autoSizeAppearance(model, parentApp);
613	    const childGapX = cluster.type === "exhibition" ? 24 : 32;
614	    const rowGapY = cluster.type === "generalization" ? 48 : 36;
615	    const childStartY = nextClusterY + parentSize.h + 42;
616	
617	    const childLayouts: Array<{ app: Appearance; x: number; y: number; w: number; h: number }> = [];
618	    let cursorX = clusterBaseX;
619	    let cursorY = childStartY;
620	    let rowHeight = 0;
621	    let minChildX = Infinity;
622	    let maxChildRight = -Infinity;
623	
624	    for (const childApp of childApps) {
625	      const childSize = autoSizeAppearance(model, childApp);
626	      if (cursorX > clusterBaseX && cursorX + childSize.w > clusterBaseX + clusterMaxWidth) {
627	        cursorX = clusterBaseX;
628	        cursorY += rowHeight + rowGapY;
629	        rowHeight = 0;
630	      }
631	      childLayouts.push({ app: childApp, x: cursorX, y: cursorY, w: childSize.w, h: childSize.h });
632	      minChildX = Math.min(minChildX, cursorX);
633	      maxChildRight = Math.max(maxChildRight, cursorX + childSize.w);
634	      rowHeight = Math.max(rowHeight, childSize.h);
635	      cursorX += childSize.w + childGapX;
636	    }
637	
638	    const childBandCenter = minChildX < Infinity && maxChildRight > -Infinity
639	      ? (minChildX + maxChildRight) / 2
640	      : clusterBaseX + parentSize.w / 2;
641	    const parentX = Math.max(40, childBandCenter - parentSize.w / 2);
642	    const parentY = nextClusterY;
643	    if (!isPinned(parentApp)) patches.push({ thingId: cluster.parentId, opdId, patch: { x: parentX, y: parentY, ...parentSize } });
644	    placed.add(cluster.parentId);
645	
646	    for (const child of childLayouts) {
647	      if (!isPinned(child.app)) {
648	        patches.push({
649	          thingId: child.app.thing,
650	          opdId,
651	          patch: { x: child.x, y: child.y, w: child.w, h: child.h },
652	        });
653	      }
654	      placed.add(child.app.thing);
655	    }
656	
657	    const clusterBottom = childLayouts.reduce((max, child) => Math.max(max, child.y + child.h), childStartY);
658	    nextClusterY = clusterBottom + 54;
659	  }
660	
661	  // Place remaining unplaced things in a separate right rail
662	  const unplaced = apps.filter((a) => !placed.has(a.thing));
663	  let remainX = 940;
664	  let remainY = 40;
665	  for (const app of unplaced) {
666	    const size = autoSizeAppearance(model, app);
667	    if (!isPinned(app)) patches.push({ thingId: app.thing, opdId, patch: { x: remainX, y: remainY, ...size } });
668	    remainY += size.h + VISUAL_RULES.spacing.nodeGap;
669	  }
670	
671	  const finalized = finalizeLayout(model, apps, links, patches);
672	  return {
673	    strategy: "structural-cluster",
674	    patches: finalized.patches,
675	    findings: finalized.findings,
676	  };
677	}
