705	  for (const proc of processes) {
706	    if (isPinned(proc)) continue;
707	    const size = autoSizeAppearance(model, { ...proc, w: Math.max(proc.w, 300), h: Math.max(proc.h, 100) });
708	    const isMain = links.some((l) => l.type === "exhibition" && l.target === proc.thing);
709	    const y = isMain ? centerY : centerY + 200;
