715	  for (const group of [agents, consumed]) {
716	    for (const app of group) {
717	      const size = autoSizeAppearance(model, app);
718	      if (!isPinned(app)) patches.push({ thingId: app.thing, opdId, patch: { x: 40, y: leftY, ...size } });
