759	export function suggestLayoutForOpd(model: Model, opdId: string): LayoutSuggestion {
760	  const opd = model.opds.get(opdId);
761	  if (!opd) return { strategy: "none", patches: [], findings: [] };
762	  const projected = buildPatchableOpdProjectionSlice(model, opdId);
763	  const apps = projected.appearances;
764	  const links = projected.links;
765	  const fans = projected.fans;
766	  if (opd.refinement_type === "in-zoom") {
767	    const branching = layoutBranchingControl(model, opdId, apps, links, fans, opd.refines ?? undefined);
768	    if (branching.strategy !== "none") return branching;
769	    return layoutInZoom(model, opdId, apps, links, opd.refines ?? undefined);
770	  }
771	  if (opd.refinement_type === "unfold") return layoutUnfold(model, opdId, apps, links, opd.refines ?? undefined);
772	
773	  // SD-level or view OPDs: prefer structural layout only when the OPD is actually dominated by structure
774	  const structuralScore = structuralDominanceScore(apps, links);
775	  if (structuralScore >= 0.65) {
776	    const structural = layoutStructuralCluster(model, opdId, apps, links);
777	    if (structural.strategy !== "none") return structural;
778	  }
779	  if (!opd.parent_opd || opd.opd_type === "view") {
780	    return layoutSdBalanced(model, opdId, apps, links);
781	  }
782	  return {
783	    strategy: "none",
784	    patches: [],
785	    findings: auditVisualOpd({ appearances: apps, links, things: model.things.values(), states: model.states.values() }),
786	  };
787	}

