  1	/**
  2	 * Edge Router — intelligent link path computation
  3	 *
  4	 * Provides curved paths for links to avoid crossings and improve
  5	 * visual clarity in dense OPD diagrams.
  6	 *
  7	 * Strategies:
  8	 * 1. Straight line for short, non-crossing links
  9	 * 2. Quadratic Bézier curve for links that cross others
 10	 * 3. Bundled parallel links (same source→target pair offset)
 11	 */
 12	
 13	import type { Point, Rect } from "./geometry";
 14	import { center } from "./geometry";
 15	
 16	export interface EdgePath {
 17	  /** SVG path `d` attribute */
 18	  d: string;
 19	  /** Midpoint for label placement */
 20	  labelPoint: Point;
 21	  /** Whether this is a curved path */
 22	  curved: boolean;
 23	}
 24	
 25	interface LinkEndpoints {
 26	  id: string;
 27	  p1: Point;
 28	  p2: Point;
 29	}
 30	
 31	/** Check if two line segments intersect */
 32	function segmentsIntersect(a1: Point, a2: Point, b1: Point, b2: Point): boolean {
 33	  const d1x = a2.x - a1.x;
 34	  const d1y = a2.y - a1.y;
 35	  const d2x = b2.x - b1.x;
 36	  const d2y = b2.y - b1.y;
 37	
 38	  const cross = d1x * d2y - d1y * d2x;
 39	  if (Math.abs(cross) < 0.001) return false; // parallel
 40	
 41	  const t = ((b1.x - a1.x) * d2y - (b1.y - a1.y) * d2x) / cross;
 42	  const u = ((b1.x - a1.x) * d1y - (b1.y - a1.y) * d1x) / cross;
 43	
 44	  // Intersection within segments (excluding endpoints to avoid false positives at shared nodes)
 45	  return t > 0.05 && t < 0.95 && u > 0.05 && u < 0.95;
 46	}
 47	
 48	/** Count how many other links this link crosses */
 49	function countCrossings(link: LinkEndpoints, others: LinkEndpoints[]): number {
 50	  let count = 0;
 51	  for (const other of others) {
 52	    if (other.id === link.id) continue;
 53	    if (segmentsIntersect(link.p1, link.p2, other.p1, other.p2)) {
 54	      count++;
 55	    }
 56	  }
 57	  return count;
 58	}
 59	
 60	/** Compute perpendicular offset direction for a line */
 61	function perpendicular(p1: Point, p2: Point): Point {
 62	  const dx = p2.x - p1.x;
 63	  const dy = p2.y - p1.y;
 64	  const len = Math.sqrt(dx * dx + dy * dy);
 65	  if (len < 1) return { x: 0, y: -1 };
 66	  return { x: -dy / len, y: dx / len };
 67	}
 68	
 69	/** Generate a quadratic Bézier curve that bows away from crossings */
 70	function curvedPath(p1: Point, p2: Point, offset: number): EdgePath {
 71	  const mid = { x: (p1.x + p2.x) / 2, y: (p1.y + p2.y) / 2 };
 72	  const perp = perpendicular(p1, p2);
 73	  const cp = { x: mid.x + perp.x * offset, y: mid.y + perp.y * offset };
 74	
 75	  // Label point at t=0.5 on quadratic Bézier
 76	  const labelPoint = {
 77	    x: 0.25 * p1.x + 0.5 * cp.x + 0.25 * p2.x,
 78	    y: 0.25 * p1.y + 0.5 * cp.y + 0.25 * p2.y,
 79	  };
 80	
 81	  return {
 82	    d: `M ${p1.x},${p1.y} Q ${cp.x},${cp.y} ${p2.x},${p2.y}`,
 83	    labelPoint,
 84	    curved: true,
 85	  };
 86	}
 87	
 88	/** Generate a straight line path */
 89	function straightPath(p1: Point, p2: Point): EdgePath {
 90	  return {
 91	    d: `M ${p1.x},${p1.y} L ${p2.x},${p2.y}`,
 92	    labelPoint: { x: (p1.x + p2.x) / 2, y: (p1.y + p2.y) / 2 },
 93	    curved: false,
 94	  };
 95	}
 96	
 97	/** Key for parallel link detection (same source↔target pair) */
 98	function pairKey(a: string, b: string): string {
 99	  return a < b ? `${a}::${b}` : `${b}::${a}`;
100	}
101	
102	/** Key for convergent link detection (multiple sources → same target) */
103	function targetKey(targetId: string): string {
104	  return `tgt::${targetId}`;
105	}
106	
107	export interface RouteInput {
108	  id: string;
109	  sourceId: string;
110	  targetId: string;
111	  p1: Point;
112	  p2: Point;
113	}
114	
115	export interface RouteResult {
116	  id: string;
117	  path: EdgePath;
118	}
119	
120	/**
121	 * Route a batch of links, applying curves where crossings occur,
122	 * offsetting parallel links, and nudging labels to avoid collisions.
123	 */
124	export function routeEdges(links: RouteInput[]): Map<string, EdgePath> {
125	  const result = new Map<string, EdgePath>();
126	  if (links.length === 0) return result;
127	
128	  const endpoints: LinkEndpoints[] = links.map(l => ({ id: l.id, p1: l.p1, p2: l.p2 }));
129	
