149	    const group = parallelGroups.get(key)!;
150	    const convKey = targetKey(link.targetId);
151	    const convGroup = convergentGroups.get(convKey)!;
152	
153	    if (group.length > 1) {
154	      // Parallel links (same pair): offset each one
155	      const idx = group.indexOf(link);
156	      const total = group.length;
157	      const spread = Math.min(30, Math.max(15, 60 / total)); // adaptive spread
158	      const offset = (idx - (total - 1) / 2) * spread;
159	
160	      if (Math.abs(offset) < 1) {
161	        const crossings = countCrossings({ id: link.id, p1: link.p1, p2: link.p2 }, endpoints);
162	        if (crossings > 0) {
163	          result.set(link.id, curvedPath(link.p1, link.p2, 25 + crossings * 10));
164	        } else {
165	          result.set(link.id, straightPath(link.p1, link.p2));
166	        }
167	      } else {
168	        result.set(link.id, curvedPath(link.p1, link.p2, offset));
169	      }
170	    } else if (convGroup.length >= 3) {
171	      // Convergent links: 3+ links from different sources to same target
172	      // Offset them so they don't all arrive at exactly the same point
173	      const idx = convGroup.indexOf(link);
174	      const total = convGroup.length;
175	      const spread = Math.min(25, Math.max(12, 50 / total));
176	      const offset = (idx - (total - 1) / 2) * spread;
177	
178	      if (Math.abs(offset) < 2) {
