 50	function intersectionArea(a: Rect, b: Rect): number {
 51	  const x = Math.max(0, Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x));
 52	  const y = Math.max(0, Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y));
 53	  return x * y;
 54	}
 55	
 56	function appearanceRect(a: Pick<Appearance, "x" | "y" | "w" | "h">): Rect {
 57	  return { x: a.x, y: a.y, w: a.w, h: a.h };
 58	}
 59	
 60	function axisGap(a: Rect, b: Rect): { axis: "x" | "y"; gap: number } | null {
 61	  const overlapX = Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x);
 62	  const overlapY = Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y);
 63	  if (overlapX > 0 && overlapY > 0) return null;
 64	  if (overlapY > 0) {
 65	    const gap = Math.max(b.x - (a.x + a.w), a.x - (b.x + b.w));
 66	    return { axis: "x", gap };
 67	  }
 68	  if (overlapX > 0) {
 69	    const gap = Math.max(b.y - (a.y + a.h), a.y - (b.y + b.h));
 70	    return { axis: "y", gap };
 71	  }
 72	  return null;
 73	}
