 75	export function findNonContainerOverlaps(appearances: Appearance[]): OverlapFinding[] {
 76	  const visible = appearances.filter((a) => !a.internal);
 77	  const findings: OverlapFinding[] = [];
 78	  for (let i = 0; i < visible.length; i++) {
 79	    for (let j = i + 1; j < visible.length; j++) {
 80	      const a = visible[i];
 81	      const b = visible[j];
 82	      if (!a || !b) continue;
 83	      const area = intersectionArea(appearanceRect(a), appearanceRect(b));
 84	      if (area > 0) {
 85	        findings.push({ kind: "overlap", aThing: a.thing, bThing: b.thing, area });
 86	      }
 87	    }
 88	  }
 89	  return findings.sort((a, b) => b.area - a.area);
 90	}
